def transpose_song(song, key):
    # Song is a dictionary with 'chords', 'capo', and 'key' as keys
    chords = song['chords']
    capo = song['capo']
    original_key = song['key']

    # Define chord substitutions for transposition
    chord_subs = {
        'A': {'A': 'A', 'B': 'A#', 'C': 'B', 'D': 'C', 'E': 'C#', 'F': 'D', 'G': 'D#'},
        'A#': {'A': 'A#', 'B': 'B', 'C': 'C', 'D': 'C#', 'E': 'D', 'F': 'D#', 'G': 'E'},
        'B': {'A': 'B', 'B': 'C', 'C': 'C#', 'D': 'D', 'E': 'D#', 'F': 'E', 'G': 'F'},
        'C': {'A': 'C', 'B': 'C#', 'C': 'D', 'D': 'D#', 'E': 'E', 'F': 'F', 'G': 'F#'},
        'C#': {'A': 'C#', 'B': 'D', 'C': 'D#', 'D': 'E', 'E': 'F', 'F': 'F#', 'G': 'G'},
        'D': {'A': 'D', 'B': 'D#', 'C': 'E', 'D': 'F', 'E': 'F#', 'F': 'G', 'G': 'G#'},
        'D#': {'A': 'D#', 'B': 'E', 'C': 'F', 'D': 'F#', 'E': 'G', 'F': 'G#', 'G': 'A'},
        'E': {'A': 'E', 'B': 'F', 'C': 'F#', 'D': 'G', 'E': 'G#', 'F': 'A', 'G': 'A#'},
        'F': {'A': 'F', 'B': 'F#', 'C': 'G', 'D': 'G#', 'E': 'A', 'F': 'A#', 'G': 'B'},
        'F#': {'A': 'F#', 'B': 'G', 'C': 'G#', 'D': 'A', 'E': 'A#', 'F': 'B', 'G': 'C'},
        'G': {'A': 'G', 'B': 'G#', 'C': 'A', 'D': 'A#', 'E': 'B', 'F': 'C', 'G': 'C#'},
        'G#': {'A': 'G#', 'B': 'A', 'C': 'A#', 'D': 'B', 'E': 'C', 'F': 'C#', 'G': 'D'}
    }

    # Transpose chords
    transposed_chords = []
    for chord in chords:
        if chord in chord_subs[original_key]:
            transposed_chords.append(chord_subs[key][chord_subs[original_key][chord]])
        else:
            transposed_chords.append(chord)

    return {'chords': transposed_chords, 'capo': capo + (key.index - original_key.index), 'key': key}

