# Query to determine the shelf life of specific ingredients
def get_shelf_life(ingredients):
    shelf_life_dict = {
        "roasted poblanos": 3,
        "picadillo filling": 3,
        "walnut sauce": 5,
        "cream": 7  # assuming heavy cream or whipping cream
    }
    return {ingredient: shelf_life_dict.get(ingredient, "Unknown") for ingredient in ingredients}

